def rc(s): return "".join(comp[c] for c in reversed(s))

# ORF scan both strands
def orfs(s, min_aa=50):
    res=[]
    for strand, sq in (("+", s), ("-", rc(s))):
        for frame in range(3):
            i=frame
            while i < len(sq)-2:
                if sq[i:i+3]=="ATG":
